-- Создание процедуры
CREATE OR REPLACE PROCEDURE update_salary(
    p_employee_id INT,
    p_new_salary NUMERIC
)
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE employees
    SET salary = p_new_salary
    WHERE id = p_employee_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Сотрудник не найден';
    END IF;
END;
$$;

-- Вызов процедуры
CALL update_salary(1, 75000);

-- Создание функции
CREATE OR REPLACE FUNCTION get_full_name(
    p_employee_id INT
)
RETURNS VARCHAR
LANGUAGE plpgsql
AS $$
DECLARE
    full_name VARCHAR;
BEGIN
    SELECT first_name || ' ' || last_name
    INTO full_name
    FROM employees
    WHERE id = p_employee_id;

    RETURN full_name;
END;
$$;

