USE company;

-- Создание таблицы с большим количеством данных
CREATE TABLE IF NOT EXISTS orders (
    id INT PRIMARY KEY AUTO_INCREMENT,
    customer_id INT NOT NULL,
    order_date DATE NOT NULL,
    amount DECIMAL(12, 2),
    status VARCHAR(20) DEFAULT 'new'
);

-- Добавление тестовых данных
DELIMITER //
CREATE PROCEDURE fill_orders()
BEGIN
    DECLARE i INT DEFAULT 1;
    WHILE i <= 10000 DO
        INSERT INTO orders (customer_id, order_date, amount, status)
        VALUES (
            FLOOR(1 + RAND() * 1000),
            DATE_ADD('2020-01-01', INTERVAL FLOOR(RAND() * 2000) DAY),
            ROUND(RAND() * 100000, 2),
            ELT(FLOOR(1 + RAND() * 3), 'new', 'processing', 'done')
        );
        SET i = i + 1;
    END WHILE;
END //
DELIMITER ;

-- Заполнение
CALL fill_orders();

-- Замер времени выполнения запроса
