USE company;

-- Создание таблицы счетов
CREATE TABLE IF NOT EXISTS accounts (
    id INT PRIMARY KEY AUTO_INCREMENT,
    owner VARCHAR(100) NOT NULL,
    balance DECIMAL(10, 2) NOT NULL DEFAULT 0.00
);

-- Добавление данных
INSERT INTO accounts (owner, balance) VALUES
    ('Иванов', 1000.00),
    ('Петров', 500.00);

-- Начало транзакции
START TRANSACTION;

-- Операции
UPDATE accounts SET balance = balance - 100 WHERE owner = 'Иванов';
UPDATE accounts SET balance = balance + 100 WHERE owner = 'Петров';

-- Фиксация изменений
COMMIT;

-- Начало транзакции
START TRANSACTION;

-- Ошибочная операция
UPDATE accounts SET balance = balance - 100 WHERE owner = 'Иванов';
UPDATE accounts SET balance = balance + 100 WHERE owner = 'Неизвестный';

-- Отмена всех изменений
ROLLBACK;

DELIMITER //

CREATE PROCEDURE transfer_money(
    IN from_owner VARCHAR(100),
    IN to_owner VARCHAR(100),
    IN amount DECIMAL(10, 2)
)
BEGIN
    DECLARE current_balance DECIMAL(10, 2);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 'Ошибка, транзакция отменена' AS result;
    END;

    START TRANSACTION;

    -- Получение баланса отправителя
    SELECT balance INTO current_balance
    FROM accounts
    WHERE owner = from_owner
    FOR UPDATE;

    -- Проверка достаточности средств
    IF current_balance < amount THEN
        ROLLBACK;
        SELECT 'Недостаточно средств' AS result;
    ELSE
        -- Перевод
        UPDATE accounts SET balance = balance - amount WHERE owner = from_owner;
        UPDATE accounts SET balance = balance + amount WHERE owner = to_owner;
        COMMIT;
        SELECT 'Перевод выполнен' AS result;
    END IF;
END //

DELIMITER ;

