-- 1. Создать процедуру с полной обработкой ошибок
DELIMITER //
CREATE PROCEDURE safe_transfer(
    IN from_id INT,
    IN to_id INT,
    IN amount DECIMAL(10, 2)
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 'Ошибка транзакции' AS status;
    END;

    START TRANSACTION;

    UPDATE accounts 
    SET balance = balance - amount 
    WHERE id = from_id AND balance >= amount;

    IF ROW_COUNT() = 0 THEN
        ROLLBACK;
        SELECT 'Недостаточно средств' AS status;
    ELSE
        UPDATE accounts 
        SET balance = balance + amount 
        WHERE id = to_id;

        COMMIT;
        SELECT 'Перевод выполнен' AS status;
    END IF;
END //
DELIMITER ;

