DELIMITER //

CREATE PROCEDURE calculate_stats()
BEGIN
    -- Локальные переменные
    DECLARE total_salary DECIMAL(12, 2);
    DECLARE employee_count INT;
    DECLARE avg_salary DECIMAL(12, 2);

    -- Вычисление
    SELECT SUM(salary) INTO total_salary FROM employees;
    SELECT COUNT(*) INTO employee_count FROM employees;

    IF employee_count > 0 THEN
        SET avg_salary = total_salary / employee_count;
    ELSE
        SET avg_salary = 0;
    END IF;

    -- Вывод результатов
    SELECT 
        total_salary AS total,
        employee_count AS count,
        avg_salary AS average;
END //

DELIMITER ;

