CREATE PROCEDURE get_employee_level(
    IN p_employee_id INT
)
BEGIN
    DECLARE emp_salary DECIMAL(10, 2);
    DECLARE emp_name VARCHAR(100);

    -- Получение данных
    SELECT CONCAT(first_name, ' ', last_name), salary
    INTO emp_name, emp_salary
    FROM employees
    WHERE id = p_employee_id;

    -- Условная логика
    IF emp_salary >= 80000 THEN
        SELECT emp_name AS name, emp_salary AS salary, 'Высокий уровень' AS level;
    ELSEIF emp_salary >= 60000 THEN
        SELECT emp_name AS name, emp_salary AS salary, 'Средний уровень' AS level;
    ELSEIF emp_salary >= 40000 THEN
        SELECT emp_name AS name, emp_salary AS salary, 'Начальный уровень' AS level;
    ELSE
        SELECT emp_name AS name, emp_salary AS salary, 'Низкий уровень' AS level;
    END IF;
END //

DELIMITER ;

