CALL get_employee_level(1);

DELIMITER //

CREATE PROCEDURE fill_test_data(
    IN p_count INT
)
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE random_name VARCHAR(50);
    DECLARE random_salary DECIMAL(10, 2);

    WHILE i <= p_count DO
        SET random_name = CONCAT('Сотрудник ', i);
        SET random_salary = 40000 + RAND() * 40000;

        INSERT INTO employees (first_name, last_name, email, department_id, salary)
        VALUES (random_name, 'Тестовый', CONCAT('test', i, '@company.ru'), 
                FLOOR(1 + RAND() * 3), random_salary);

        SET i = i + 1;
    END WHILE;

    SELECT CONCAT('Добавлено ', p_count, ' записей') AS result;
END //

DELIMITER ;

-- Вызов: добавить 10 тестовых записей
CALL fill_test_data(10);

DELIMITER //

CREATE PROCEDURE process_all_employees()
BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE emp_name VARCHAR(100);
    DECLARE emp_salary DECIMAL(10, 2);

    -- Курсор для перебора строк
    DECLARE emp_cursor CURSOR FOR
        SELECT CONCAT(first_name, ' ', last_name), salary
        FROM employees;

    -- Обработчик окончания
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN emp_cursor;

    read_loop: LOOP
        FETCH emp_cursor INTO emp_name, emp_salary;

        IF done = 1 THEN
            LEAVE read_loop;
        END IF;

        -- Обработка каждой строки
        SELECT CONCAT(emp_name, ' — ', emp_salary) AS employee_info;
    END LOOP;

    CLOSE emp_cursor;
END //

DELIMITER ;

