-- 1. Создать процедуру повышения зарплаты всем сотрудникам отдела
DELIMITER //
CREATE PROCEDURE raise_department_salary(
    IN p_department_id INT,
    IN p_percent DECIMAL(5, 2)
)
BEGIN
    DECLARE updated_count INT;

    UPDATE employees
    SET salary = salary * (1 + p_percent / 100)
    WHERE department_id = p_department_id;

    SET updated_count = ROW_COUNT();

    SELECT CONCAT('Обновлено сотрудников: ', updated_count) AS result;
END //
DELIMITER ;

-- 2. Создать триггер на изменение зарплаты
DELIMITER //
CREATE TRIGGER salary_change_log
AFTER UPDATE ON employees
FOR EACH ROW
BEGIN
    IF OLD.salary != NEW.salary THEN
        INSERT INTO employees_log (employee_id, action, old_value, new_value)
        VALUES (NEW.id, 'SALARY_CHANGE', OLD.salary, NEW.salary);
    END IF;
END //
DELIMITER ;

