import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.zip.ZipOutputStream;

public class ZipExample {

    public static void main(String[] args) {
        createZipArchive();
        readZipArchive();
    }

    public static void createZipArchive() {
        try (ZipOutputStream zip = new ZipOutputStream(
                new FileOutputStream("archive.zip"))) {

            // Добавляем первый файл
            ZipEntry entry1 = new ZipEntry("first.txt");
            zip.putNextEntry(entry1);
            zip.write("Первый файл в архиве".getBytes());
            zip.closeEntry();

            // Добавляем второй файл
            ZipEntry entry2 = new ZipEntry("second.txt");
            zip.putNextEntry(entry2);
            zip.write("Второй файл в архиве".getBytes());
            zip.closeEntry();

            System.out.println("Архив создан");

        } catch (IOException e) {
            System.out.println("Ошибка создания архива: " + e.getMessage());
        }
    }

    public static void readZipArchive() {
        try (ZipInputStream zip = new ZipInputStream(
                new FileInputStream("archive.zip"))) {

            ZipEntry entry;
            while ((entry = zip.getNextEntry()) != null) {
                System.out.println("Файл в архиве: " + entry.getName());
                System.out.println("Размер: " + entry.getSize() + " байт");

                // Чтение содержимого
                byte[] data = zip.readAllBytes();
                System.out.println("Содержимое: " + new String(data));
                System.out.println();

                zip.closeEntry();
            }

        } catch (IOException e) {
            System.out.println("Ошибка чтения архива: " + e.getMessage());
        }
    }
}

