// Adapter — адаптируем старый интерфейс к новому
// Старый класс
class OldPrinter {
    public void printOld(String text) {
        System.out.println("Печать: " + text);
    }
}

// Новый интерфейс
interface ModernPrinter {
    void print(String text);
}

// Адаптер
class PrinterAdapter implements ModernPrinter {
    private OldPrinter oldPrinter;

    public PrinterAdapter(OldPrinter oldPrinter) {
        this.oldPrinter = oldPrinter;
    }

    @Override
    public void print(String text) {
        oldPrinter.printOld(text);
    }
}

// Использование Adapter
public class Main {
    public static void main(String[] args) {
        OldPrinter oldPrinter = new OldPrinter();
        ModernPrinter printer = new PrinterAdapter(oldPrinter);

        printer.print("Документ"); // Выведет: Печать: Документ
    }
}

// Strategy — выбор алгоритма во время выполнения
interface PaymentStrategy {
    void pay(double amount);
}

class CardPayment implements PaymentStrategy {
    private String cardNumber;

    public CardPayment(String cardNumber) {
        this.cardNumber = cardNumber;
    }

    @Override
    public void pay(double amount) {
        System.out.println("Оплата картой " + cardNumber + ": " + amount);
    }
}

class CashPayment implements PaymentStrategy {
    @Override
    public void pay(double amount) {
        System.out.println("Оплата наличными: " + amount);
    }
}

class Order {
    private PaymentStrategy paymentStrategy;

    public void setPaymentStrategy(PaymentStrategy strategy) {
        this.paymentStrategy = strategy;
    }

    public void processOrder(double amount) {
        paymentStrategy.pay(amount);
    }
}

// Использование Strategy
public class Main {
    public static void main(String[] args) {
        Order order = new Order();

        // Выбираем способ оплаты
        order.setPaymentStrategy(new CardPayment("1234-5678"));
        order.processOrder(1500.0);

        // Меняем способ оплаты
        order.setPaymentStrategy(new CashPayment());
        order.processOrder(500.0);
    }
}

