package com.example.loginapp;

import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import android.widget.Button;
import android.widget.EditText;
import android.widget.TextView;

public class MainActivity extends Activity {

    // Тестовые данные для входа
    private static final String VALID_LOGIN = "admin";
    private static final String VALID_PASSWORD = "1234";

    private EditText loginInput;
    private EditText passwordInput;
    private TextView errorText;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Шаг 1: находим элементы
        loginInput = findViewById(R.id.loginInput);
        passwordInput = findViewById(R.id.passwordInput);
        errorText = findViewById(R.id.errorText);
        Button loginButton = findViewById(R.id.loginButton);

        // Шаг 2: обработка кнопки
        loginButton.setOnClickListener(v -> checkLogin());
    }

    private void checkLogin() {
        // Шаг 3: читаем ввод
        String login = loginInput.getText().toString().trim();
        String password = passwordInput.getText().toString().trim();

        // Шаг 4: проверяем на пустоту
        if (login.isEmpty() || password.isEmpty()) {
            errorText.setText("Заполните все поля");
            return;
        }

        // Шаг 5: сверяем с тестовыми данными
        if (login.equals(VALID_LOGIN) && password.equals(VALID_PASSWORD)) {
            errorText.setText("");

            // Шаг 6: переход на главный экран
            Intent intent = new Intent(MainActivity.this, HomeActivity.class);
            intent.putExtra("username", login);
            startActivity(intent);
            finish();
        } else {
            errorText.setText("Неверный логин или пароль");
        }
    }
}

