package com.example.myfirstapp;

/**
 * Модуль для проверки текста
 */
public class Validator {

    /**
     * Проверяет длину текста
     * @param text — текст для проверки
     * @return true, если текст допустимой длины
     */
    public static boolean isValidLength(String text) {
        if (text == null) {
            return false;
        }
        return text.length() >= Constants.MIN_TEXT_LENGTH 
            && text.length() <= Constants.MAX_TEXT_LENGTH;
    }

    /**
     * Проверяет, что текст не пустой
     */
    public static boolean isNotEmpty(String text) {
        return text != null && !text.trim().isEmpty();
    }

    /**
     * Проверяет, что текст содержит только буквы и цифры
     */
    public static boolean isAlphanumeric(String text) {
        if (text == null || text.isEmpty()) {
            return false;
        }
        return text.matches("[a-zA-Zа-яА-Я0-9]+");
    }
}

