package com.example.myfirstapp;

import android.app.Activity;
import android.os.Bundle;
import android.widget.Button;
import android.widget.TextView;

public class MainActivity extends Activity {

    private TextView display;
    private double firstNumber = 0;
    private String operation = "";
    private boolean isNewInput = true;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        display = findViewById(R.id.display);
        setupNumberButtons();
        setupOperationButtons();
    }

    private void setupNumberButtons() {
        int[] buttonIds = {
            R.id.btn0, R.id.btn1, R.id.btn2, R.id.btn3, R.id.btn4,
            R.id.btn5, R.id.btn6, R.id.btn7, R.id.btn8, R.id.btn9
        };

        for (int id : buttonIds) {
            Button button = findViewById(id);
            button.setOnClickListener(v -> {
                String digit = button.getText().toString();

                if (isNewInput) {
                    display.setText(digit);
                    isNewInput = false;
                } else {
                    String current = display.getText().toString();
                    display.setText(current + digit);
                }
            });
        }
    }

    private void setupOperationButtons() {
        Button addButton = findViewById(R.id.btnAdd);
        Button subtractButton = findViewById(R.id.btnSubtract);
        Button multiplyButton = findViewById(R.id.btnMultiply);
        Button divideButton = findViewById(R.id.btnDivide);
        Button equalsButton = findViewById(R.id.btnEquals);
        Button clearButton = findViewById(R.id.btnClear);

        addButton.setOnClickListener(v -> setOperation("+"));
        subtractButton.setOnClickListener(v -> setOperation("-"));
        multiplyButton.setOnClickListener(v -> setOperation("×"));
        divideButton.setOnClickListener(v -> setOperation("÷"));

        equalsButton.setOnClickListener(v -> calculate());

        clearButton.setOnClickListener(v -> {
            display.setText("0");
            firstNumber = 0;
            operation = "";
            isNewInput = true;
        });
    }

    private void setOperation(String op) {
        firstNumber = Double.parseDouble(display.getText().toString());
        operation = op;
        isNewInput = true;
    }

    private void calculate() {
        double secondNumber = Double.parseDouble(display.getText().toString());
        double result = 0;

        switch (operation) {
            case "+":
                result = firstNumber + secondNumber;
                break;
            case "-":
                result = firstNumber - secondNumber;
                break;
            case "×":
                result = firstNumber * secondNumber;
                break;
            case "÷":
                if (secondNumber == 0) {
                    display.setText("Ошибка");
                    isNewInput = true;
                    return;
                }
                result = firstNumber / secondNumber;
                break;
            default:
                return;
        }

        // Отображение результата
        if (result == (long) result) {
            display.setText(String.valueOf((long) result));
        } else {
            display.setText(String.valueOf(result));
        }

        isNewInput = true;
    }
}

